use bfsgraph::Graph;

#[test]
fn test_shortest_path_direct() {
    let mut g = Graph::new(4);
    g.add_edge(0, 1);
    g.add_edge(1, 2);
    g.add_edge(2, 3);
    assert_eq!(g.bfs_shortest_path(0, 3), Some(3));
    assert_eq!(g.bfs_shortest_path(0, 1), Some(1));
}

#[test]
fn test_shortest_path_no_connection() {
    let mut g = Graph::new(4);
    g.add_edge(0, 1);
    // node 2 and 3 are disconnected
    assert_eq!(g.bfs_shortest_path(0, 3), None);
}

#[test]
fn test_shortest_path_same_node() {
    let g = Graph::new(3);
    assert_eq!(g.bfs_shortest_path(0, 0), Some(0));
}

#[test]
fn test_bfs_all_distances() {
    let mut g = Graph::new(5);
    g.add_edge(0, 1);
    g.add_edge(0, 2);
    g.add_edge(1, 3);
    g.add_edge(2, 4);
    let dists = g.bfs_all_distances(0);
    assert_eq!(dists[0], Some(0));
    assert_eq!(dists[1], Some(1));
    assert_eq!(dists[2], Some(1));
    assert_eq!(dists[3], Some(2));
    assert_eq!(dists[4], Some(2));
}

#[test]
fn test_shortest_path_shortcut() {
    let mut g = Graph::new(4);
    g.add_edge(0, 1);
    g.add_edge(1, 3);
    g.add_edge(0, 2);
    g.add_edge(2, 3);
    // Both paths have length 2
    assert_eq!(g.bfs_shortest_path(0, 3), Some(2));
}

